'use client';

import * as React from 'react';
import { Drawer as DrawerPrimitive } from 'vaul';

import { ModalPortalScope, useRootPortalContainer } from '@/components/ui/portal';
import { cn } from '@/lib/utils';

function Drawer({ ...props }: React.ComponentProps<typeof DrawerPrimitive.Root>) {
	return <DrawerPrimitive.Root data-slot="drawer" {...props} />;
}

function DrawerTrigger({ ...props }: React.ComponentProps<typeof DrawerPrimitive.Trigger>) {
	return <DrawerPrimitive.Trigger data-slot="drawer-trigger" {...props} />;
}

function DrawerPortal({ container: containerProp, ...props }: React.ComponentProps<typeof DrawerPrimitive.Portal>) {
	const rootContainer = useRootPortalContainer();
	const container = containerProp === undefined ? (rootContainer ?? undefined) : containerProp;
	return <DrawerPrimitive.Portal data-slot="drawer-portal" container={container} {...props} />;
}

function DrawerClose({ ...props }: React.ComponentProps<typeof DrawerPrimitive.Close>) {
	return <DrawerPrimitive.Close data-slot="drawer-close" {...props} />;
}

function DrawerOverlay({ className, ...props }: React.ComponentProps<typeof DrawerPrimitive.Overlay>) {
	return (
		<DrawerPrimitive.Overlay
			data-slot="drawer-overlay"
			className={cn(
				`fixed inset-0 z-[var(--z-layer-modal-backdrop)] bg-black/32 backdrop-blur-sm
				data-[state=open]:animate-[fade-in_200ms_ease-out] data-[state=closed]:animate-[fade-out_150ms_ease-in]
				motion-reduce:animate-none`,
				className,
			)}
			{...props}
		/>
	);
}

function DrawerContent({ className, children, ...props }: React.ComponentProps<typeof DrawerPrimitive.Content>) {
	const [floatingContainer, setFloatingContainer] = React.useState<HTMLDivElement | null>(null);

	return (
		<DrawerPortal>
			<DrawerOverlay />
			<DrawerPrimitive.Content
				data-slot="drawer-content"
				className={cn(
					'group/drawer-content bg-background fixed z-[var(--z-layer-modal-content)] flex h-auto flex-col',
					`data-[vaul-drawer-direction=top]:inset-x-0 data-[vaul-drawer-direction=top]:top-0
					data-[vaul-drawer-direction=top]:mb-24 data-[vaul-drawer-direction=top]:max-h-[80vh]
					data-[vaul-drawer-direction=top]:rounded-b-xl data-[vaul-drawer-direction=top]:border-b`,
					`data-[vaul-drawer-direction=bottom]:inset-x-0 data-[vaul-drawer-direction=bottom]:bottom-0
					data-[vaul-drawer-direction=bottom]:mt-24 data-[vaul-drawer-direction=bottom]:max-h-[80vh]
					data-[vaul-drawer-direction=bottom]:rounded-t-xl data-[vaul-drawer-direction=bottom]:border-t`,
					`data-[vaul-drawer-direction=right]:inset-y-0 data-[vaul-drawer-direction=right]:right-0
					data-[vaul-drawer-direction=right]:w-3/4 data-[vaul-drawer-direction=right]:border-l
					data-[vaul-drawer-direction=right]:sm:max-w-sm`,
					`data-[vaul-drawer-direction=left]:inset-y-0 data-[vaul-drawer-direction=left]:left-0
					data-[vaul-drawer-direction=left]:w-3/4 data-[vaul-drawer-direction=left]:border-r
					data-[vaul-drawer-direction=left]:sm:max-w-sm`,
					className,
				)}
				{...props}
			>
				<div
					className='bg-muted mx-auto mt-4 hidden h-2 w-[100px] shrink-0 rounded-full
						group-data-[vaul-drawer-direction=bottom]/drawer-content:block'
				/>
				{/* The body scrolls; the portal host below stays outside it so menus and popovers opened inside the drawer are not clipped. */}
				<div
					data-slot='drawer-body'
					className='flex min-h-0 flex-1 flex-col overflow-y-auto overscroll-contain [overflow-wrap:break-word]'
				>
					<ModalPortalScope floatingContainer={floatingContainer} floatingZIndex='elevated'>
						{children}
					</ModalPortalScope>
				</div>
				<div ref={setFloatingContainer} data-slot='drawer-floating-portal' className='contents' />
			</DrawerPrimitive.Content>
		</DrawerPortal>
	);
}

function DrawerHeader({ className, ...props }: React.ComponentProps<'div'>) {
	return (
		<div
			data-slot="drawer-header"
			className={cn(
				`flex flex-col gap-0.5 p-4 group-data-[vaul-drawer-direction=bottom]/drawer-content:text-center
				group-data-[vaul-drawer-direction=top]/drawer-content:text-center md:gap-1.5 md:text-start`,
				className,
			)}
			{...props}
		/>
	);
}

function DrawerFooter({ className, ...props }: React.ComponentProps<'div'>) {
	return <div data-slot="drawer-footer" className={cn('mt-auto flex flex-col gap-2 p-4', className)} {...props} />;
}

function DrawerTitle({ className, ...props }: React.ComponentProps<typeof DrawerPrimitive.Title>) {
	return (
		<DrawerPrimitive.Title
			data-slot="drawer-title"
			className={cn('text-foreground font-semibold', className)}
			{...props}
		/>
	);
}

function DrawerDescription({ className, ...props }: React.ComponentProps<typeof DrawerPrimitive.Description>) {
	return (
		<DrawerPrimitive.Description
			data-slot="drawer-description"
			className={cn('text-muted-foreground text-sm', className)}
			{...props}
		/>
	);
}

export {
	Drawer,
	DrawerPortal,
	DrawerOverlay,
	DrawerTrigger,
	DrawerClose,
	DrawerContent,
	DrawerHeader,
	DrawerFooter,
	DrawerTitle,
	DrawerDescription,
};
